<div class="d-flex justify-content-between"><h2>Stock</h2><a class="btn btn-primary" href="<?=url('/stock/nuevo')?>">Nuevo</a></div><p class="text-muted">CRUD interno Puchún.</p><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Fecha</th><th>Almacén</th><th>Items</th><th>Cantidad</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['fecha_stock'])?></td><td><?=e($r['almacen'])?></td><td><?=e($r['items'])?></td><td><?=e($r['cantidad'])?></td><td><?=e($r['estado_registro'])?></td><td><?php if(has_role('ADMIN','SUPERVISOR')):?><form method="post" action="<?=url('/stock/estado')?>" class="d-flex gap-1"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status" class="form-select form-select-sm"><option>BORRADOR</option><option>VALIDADO</option><option>PUBLICADO</option></select><button class="btn btn-sm btn-success">Aplicar</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
